INSERT INTO public.lesson_content (lesson_key, course_id, title, content_html, updated_at)
VALUES
  ('kurmanji-course-1-lesson-09.html','kurmanji-course-1','ناوە کەسییەکان و شوێنەکان','<section class="klesson-card"><h2>١. بنەمای نوسینی ناوی تایبەت</h2><ul><li>ناوی کەس و شوێن لە دەستپێکدا بە پیتی گەورە دەنووسرێن: <em>Azad</em>، <em>Rojîn</em>، <em>Amed</em>.</li><li>پیتە تایبەتەکانی کورمانجی وەک ç، ş، ê، î، û لە ناوەکانیشدا دەپارێزرێن، ئەگەر لە شێوەی هەڵبژێردراوی ناوەکەدا هەبن.</li><li>ناوی کەس بە پێی شێوەی خۆی یان شێوەی فەرمیی خاوەن ناوەکە دەنووسرێت؛ نابێت بەبێ بەڵگە شێوەیەکی تر بۆی دابنرێت.</li><li>هەندێک شوێن ناوی جیاواز لە زمان و شێوەزارە جیاوازەکاندا هەیە. لە دەقی کورمانجی، شێوەی کورمانجیی ناوەکە بەکاربهێنە و لە پەیویستدا ناوی باو یان فەرمیی تر لە کەوانەدا زیاد بکە.</li></ul></section>
<section class="klesson-card"><h2>٢. نمونەی ناوە کەسییەکان</h2><table class="klesson-table"><thead><tr><th>ناو</th><th>تێبینیی ڕێنووسی</th></tr></thead><tbody><tr><td>Azad</td><td>دەستپێک بە پیتی گەورەی A.</td></tr><tr><td>Rojîn</td><td>پیتی î بە هەمان شێوەی ڕێنووسی ناوەکە دەپارێزرێت.</td></tr><tr><td>Şilan</td><td>پیتی ş دەبێت لە نوسینەوەدا نەگۆڕدرێت بۆ s.</td></tr><tr><td>Berfîn</td><td>پیتی ê/î بە پێی شێوەی ناوەکە ورد دەنووسرێت.</td></tr><tr><td>Mem û Zîn</td><td>لە ناوی ئەدەبیی ناسراودا، نوسینی ناو و پەیوەندییەکەی دەپارێزرێت.</td></tr></tbody></table><p class="klesson-note">ئەم ناوانە نمونەی ڕاهێنانن؛ مەبەست فێربونی ڕێنووسە، نەک بانگەشەی ئەوەی کە تەنها ئەم ناوانە لە ناوچەکەدا بەکاردێن.</p></section>
<section class="klesson-card"><h2>٣. نمونەی ناوی شوێن</h2><table class="klesson-table"><thead><tr><th>شێوەی ناو</th><th>ناوی ناسراوی هاوتا</th><th>تێبینی</th></tr></thead><tbody><tr><td>Amed</td><td>Diyarbakır</td><td>هەردوو شێوەکە لە بەکارهێنانی جیاوازدا دەبینرێن.</td></tr><tr><td>Hewlêr</td><td>Erbil</td><td>شێوەی ناوەکە لە زمان و کۆنتێکستدا دەگۆڕێت.</td></tr><tr><td>Wan</td><td>Van</td><td>جیاوازیی نوسین لە سیستەمی لاتینیی کورمانجی و شێوەی تورکیی ناوەکەدا دەبینرێت.</td></tr><tr><td>Qamişlo</td><td>—</td><td>پیتی ş بە ڕونی دەپارێزرێت.</td></tr></tbody></table><p>لە کاتێکدا شوێنێک چەند ناوی هەیە، بە پێی مەبەستی دەقەکە ناوی گونجاو هەڵبژێرە. لە دەقی ئەکادیمیکدا، لە یەکەم جاردا دەتوانرێت ناوی بەکارهاتوو و شێوەی هاوتاکەی پێکەوە بنووسرێن.</p></section>
<section class="klesson-card"><h2>٤. ڕێنووسی ناو لە ڕستەدا</h2><p><strong>Ez li Amedê dijîm.</strong> — من لە ئەمید دەژیم.</p><p><strong>Ez ji Qamişloyê me.</strong> — من خەڵکی قامشلۆم.</p><p><strong>Navê min Azad e.</strong> — ناوی من ئازادە.</p><p class="klesson-note">لە کورمانجیدا، ناوی شوێن لە هەندێک پێکهاتەدا دەتوانێت شێوەی ڕێزمانیی وەربگرێت؛ بۆ نمونە لەگەڵ <em>li</em> «لە» و <em>ji</em> «لە/خەڵکی». ئەم گۆڕانانە تەنها ڕێنووسی ناو نین، بەڵکو بەشێکن لە ڕێزمان و لە وانەکانی دواتردا بە فراوانی دەخوێندرێنەوە.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>ئەم ناوانە بە پیتی گەورە و پیتە تایبەتەکانیان بنووسە: rojîn، şilan، qamişlo.</li><li>سێ ناوی کەسی و دوو ناوی شوێن بنووسە؛ شێوەی نوسینەکەیان لە سەرچاوەیەکی باوەڕپێکراو بپشکنە.</li><li>ڕستەی <em>Navê min Azad e.</em> وەرگێڕە و ناوی کەسییەکە دیاری بکە.</li><li>بۆ شوێنێک کە دوو ناوی باوی هەیە، نمونەیەک بنووسە و ڕون بکەرەوە بۆچی پەیویستە کۆنتێکست دیاری بکرێت.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Kurdi School. <a href="https://kurdischool.com/grammar.html" target="_blank" rel="noopener">Kurmanji grammar</a> — نمونەی ناوی شوێن و بەکارهێنانی <em>li</em> و <em>ji</em>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">خوێندنەوەی کتێب</a>.</li><li>Navên Kurdî. <a href="https://www.kurdishnames.org/en/sources/" target="_blank" rel="noopener">سەرچاوەکان بۆ ناوە کوردییەکان</a> — بۆ پشکنینی ڕەچەڵەک و شێوەی ناوەکان، نەک وەک یاسایەکی یەکسان بۆ هەمو ناوچەکان.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-10.html','kurmanji-course-1','دەربڕینە سەرەتاییەکان','<section class="klesson-card"><h2>١. سڵاو و ماڵئاوایی</h2><table class="klesson-table"><thead><tr><th>دەربڕینی کورمانجی</th><th>واتا بە کوردی</th><th>کات و بەکارهێنان</th></tr></thead><tbody>
<tr><td>Silav!</td><td>سڵاو!</td><td>سڵاوکردنی گشتی.</td></tr>
<tr><td>Rojbaş!</td><td>بەیانیت باش / ڕۆژباش!</td><td>سڵاوێکی باو لە کاتی ڕۆژدا.</td></tr>
<tr><td>Êvarbaş!</td><td>ئێوارە باش!</td><td>سڵاوێک بۆ کاتی ئێوارە.</td></tr>
<tr><td>Şevbaş!</td><td>شەوت باش!</td><td>بۆ ماڵئاوایی، بە تایبەتی لە شەو یان کاتی خەوتندا.</td></tr>
<tr><td>Bi xatirê te!</td><td>خواحافیز / ماڵئاوایی!</td><td>ماڵئاوایی؛ بەکارهێنان دەتوانێت بە کۆنتێکست بگۆڕێت.</td></tr>
<tr><td>Bi xêr hatî!</td><td>بەخێر بێیت!</td><td>بەخێرهاتن بۆ تاک؛ شێوەکە بەپێی ژمارە و ڕەگەز دەتوانێت بگۆڕێت.</td></tr>
</tbody></table><p class="klesson-note">دەربڕینەکان لە شێوەزار و بارودۆخی کۆمەڵایەتیی جیاوازدا هەندێک جیاوازییان هەیە. لە گفتوگۆی فەرمی و نافەرمی‌دا، کۆنتێکست و شێوەی بەکارهێنان لەبەرچاو بگرە.</p></section>
<section class="klesson-card"><h2>٢. ناساندن و پرسیارکردن لە بارودۆخ</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>Tu çawa yî?</td><td>چۆنی؟ (بۆ تاک)</td></tr>
<tr><td>Ez baş im.</td><td>من باشم.</td></tr>
<tr><td>Navê min Azad e.</td><td>ناوی من ئازادە.</td></tr>
<tr><td>Tu kî yî?</td><td>تۆ کێیت؟</td></tr>
<tr><td>Ez ji ... me.</td><td>من خەڵکی ...م / لە ...م.</td></tr>
</tbody></table><p>لە نمونەی <em>Ez ji ... me</em> شوێنەکە بە ناوی گونجاو پڕ بکەرەوە. لە ڕستەی <em>Tu çawa yî?</em>، جێناوی <em>tu</em> بۆ تاکە؛ شێوەی بانگکردنی کۆ لە وانەکانی دواتردا دەخوێندرێتەوە.</p></section>
<section class="klesson-card"><h2>٣. سوپاس و داواکردنی یارمەتی</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>Spas!</td><td>سوپاس!</td><td>دەربڕینی سوپاسگوزاری.</td></tr>
<tr><td>Ji kerema xwe.</td><td>تکایە.</td><td>داواکردنی ڕێزدارانە.</td></tr>
<tr><td>Erê.</td><td>بەڵێ.</td><td>وەڵامی ئەرێنی.</td></tr>
<tr><td>Na.</td><td>نەخێر.</td><td>وەڵامی نەرێنی.</td></tr>
<tr><td>Biborîne.</td><td>ببورە.</td><td>داوای لێبوردن؛ شێوە و ڕێنووس دەتوانێت لە سەرچاوەکاندا جیاواز بێت.</td></tr>
</tbody></table></section>
<section class="klesson-card"><h2>٤. گفتوگۆی کورت</h2><p><strong>A:</strong> Silav! Tu çawa yî?</p><p><strong>B:</strong> Silav! Ez baş im, spas. Tu çawa yî?</p><p><strong>A:</strong> Ez jî baş im.</p><p class="klesson-note">واتا: A سڵاو دەکات و دەپرسێت چۆنە. B وەڵام دەدات و سوپاس دەکات، پاشان پرسیارەکە دەگەڕێنێتەوە. وشەی <em>jî</em> لێرەدا واتای «هەروەها/هەروەها من» دەگەیەنێت.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>بە کورمانجی سڵاو بکە و بپرسە کەسەکە چۆنە.</li><li>بە ڕستەیەکی سادە خۆت بناسێنە: <em>Navê min ... e.</em></li><li>بۆ «سوپاس»، «تکایە» و «بەڵێ» هاوتای کورمانجی بنووسە.</li><li>گفتوگۆی دوو کەسییەک دروست بکە کە تێیدا سڵاو، پرسیار لە بارودۆخ و سوپاس هەبێت.</li><li>دەربڕینێک هەڵبژێرە و لە دوو سەرچاوەدا شێوەی نوسین و واتاکەی بەراورد بکە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/learn/kurdish-greetings/" target="_blank" rel="noopener">Kurdish greetings and everyday phrases</a>.</li><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-11.html','kurmanji-course-1','جێناوە کەسییەکان','<section class="klesson-card"><h2>١. جێناوە ڕاستەوخۆکان</h2><p>ئەم جێناوانە لە ڕستەی ئاساییی ئێستادا زۆرجار وەک بکەر دێن.</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>کەس و ژمارە</th></tr></thead><tbody>
<tr><td>ez</td><td>من</td><td>کەسی یەکەم، تاک</td></tr>
<tr><td>tu</td><td>تۆ</td><td>کەسی دووەم، تاک</td></tr>
<tr><td>ew</td><td>ئەو</td><td>کەسی سێیەم، تاک</td></tr>
<tr><td>em</td><td>ئێمە</td><td>کەسی یەکەم، کۆ</td></tr>
<tr><td>hûn</td><td>ئێوە / ئێوەی بەڕێز</td><td>کەسی دووەم، کۆ؛ لە هەندێک کۆنتێکستدا بۆ ڕێزگرتنیش.</td></tr>
<tr><td>ew</td><td>ئەوان</td><td>کەسی سێیەم، کۆ</td></tr>
</tbody></table><p class="klesson-note">جێناوی <em>ew</em> بەپێی کۆنتێکست دەتوانێت واتای «ئەو» یان «ئەوان» بدات. لە نوسین و گفتوگۆدا، کردار و دەوروبەری ڕستە یارمەتی دەدەن ژمارەکە بناسرێت.</p></section>
<section class="klesson-card"><h2>٢. نمونە لە ڕستەی سادەدا</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th><th>جێناو</th></tr></thead><tbody>
<tr><td>Ez xwendekar im.</td><td>من خوێندکارم.</td><td>ez</td></tr>
<tr><td>Tu baş î.</td><td>تۆ باشیت.</td><td>tu</td></tr>
<tr><td>Ew mamoste ye.</td><td>ئەو مامۆستایە.</td><td>ew</td></tr>
<tr><td>Em li vir in.</td><td>ئێمە لێرەین.</td><td>em</td></tr>
<tr><td>Hûn baş in.</td><td>ئێوە باشن.</td><td>hûn</td></tr>
<tr><td>Ew hevalên min in.</td><td>ئەوان هاوڕێکانی منن.</td><td>ew</td></tr>
</tbody></table><p>لە ڕستەکانی ناساندندا، پاش جێناو شێوەی گونجاوی پەیوەندیی «بوون» دێت؛ وەک <em>im</em>، <em>î</em>، <em>ye</em> و <em>in</em>. ئەم شێوانە بە پێی کۆتاییی ناو یان هاوەڵناو و ڕێکخستنی ڕستە دەتوانن جیاواز بن.</p></section>
<section class="klesson-card"><h2>٣. جێناوە ناڕاستەوخۆکان</h2><p>کورمانجی جگە لە شێوەی ڕاستەوخۆ، کۆمەڵێک شێوەی ناڕاستەوخۆی جێناوی هەیە. ئەم شێوانە لە خاوەنداریدا، دوای پێشگرەکان و لە هەندێک ڕستەی کرداریدا بەکاردێن. بەکارهێنانیان تەنها بە یاسای «ڕابردوو» کورت ناکرێتەوە.</p><table class="klesson-table"><thead><tr><th>ڕاستەوخۆ</th><th>ناڕاستەوخۆ</th><th>واتای بنەڕەتی</th></tr></thead><tbody>
<tr><td>ez</td><td>min</td><td>من / ـی من</td></tr>
<tr><td>tu</td><td>te</td><td>تۆ / ـی تۆ</td></tr>
<tr><td>ew</td><td>wî (نێر) / wê (مێ)</td><td>ئەو / ـی ئەو</td></tr>
<tr><td>em</td><td>me</td><td>ئێمە / ـی ئێمە</td></tr>
<tr><td>hûn</td><td>we</td><td>ئێوە / ـی ئێوە</td></tr>
<tr><td>ew</td><td>wan</td><td>ئەوان / ـی ئەوان</td></tr>
</tbody></table><p><strong>نمونە:</strong> <em>navê min</em> = ناوی من؛ <em>bi te re</em> = لەگەڵ تۆ. لەم دوو نمونەدا <em>min</em> و <em>te</em> شێوەی ناڕاستەوخۆن.</p><p class="klesson-note">جیاوازیی ڕاستەوخۆ و ناڕاستەوخۆ لە کورمانجیدا بابەتێکی گرنگی ڕێزمانە. بەکارهێنانی شێوەکان بە پێی پێکهاتەی ڕستە و کردار دەگۆڕێت؛ وردەکارییەکانی دواتر لە وانەکانی ڕێزماندا دەخوێندرێنەوە.</p></section>
<section class="klesson-card"><h2>٤. جێناوی ڕەنگدانەوەیی</h2><p><em>xwe</em> جێناوێکی ڕەنگدانەوەییە کە لە چەند کۆنتێکستێکدا بەکاردێت بۆ ئەوەی بگەڕێتەوە بۆ بکەری ڕستە.</p><p><strong>Ez ji dayika xwe hez dikim.</strong> — من خۆشم لە دایکی خۆم دەوێت.</p><p>لە نمونەکەدا <em>xwe</em> پەیوەندی بە بکەری <em>Ez</em> ـەوە هەیە. وردەکاریی بەکارهێنانی <em>xwe</em> و جێناوەکانی تر لە وانەیەکی تایبەتدا زیاتر دەکرێتەوە.</p></section>
<section class="klesson-card"><h2>٥. ڕاهێنان</h2><ol><li>واتای ئەم جێناوانە بنووسە: <em>ez, tu, ew, em, hûn, ew</em>.</li><li>لە ڕستەی <em>Em li vir in.</em> جێناوی کەسی دیاری بکە و واتای ڕستەکە بنووسە.</li><li>جێناوی ڕاستەوخۆ و ناڕاستەوخۆی <em>ez</em>، <em>tu</em> و <em>em</em> لە خشتەیەکدا جیا بکەرەوە.</li><li>واتای <em>navê min</em> و <em>bi te re</em> بنووسە و جێناوی ناڕاستەوخۆ دیاری بکە.</li><li>بە جێناوی <em>xwe</em> ڕستەیەکی سادە بنووسە و ڕون بکەرەوە بۆ چی بەکارت هێناوە.</li></ol></section>
<section class="klesson-card"><h2>٦. سەرچاوەکان</h2><ol><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — Syntax and Pronouns</a>.</li><li>Haig, Geoffrey (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>Thackston, W. M. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-12.html','kurmanji-course-1','جێناوە ئاماژەییەکان','<section class="klesson-card"><h2>١. ئاماژەکردن بە نزیک و دوور</h2><p>لە کورمانجیدا شێوەی ئاماژەیی بە پێی نزیکی و دووری و پێکهاتەی ڕستە دەگۆڕێت. لە فێربونی سەرەتاییدا ئەم دوو جیاوازییە گرنگن:</p><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتای نزیک</th><th>واتای دوور</th></tr></thead><tbody>
<tr><td>ev</td><td>ئەمە / ئەم</td><td>—</td></tr>
<tr><td>ew</td><td>—</td><td>ئەوە / ئەو</td></tr>
</tbody></table><p class="klesson-note">شێوەی <em>ew</em> هەروەها جێناوی کەسیی سێیەمیشە (ئەو/ئەوان). واتاکەی لە کۆنتێکست و پێکهاتەی ڕستەوە دەردەکەوێت؛ بۆیە نابێت هەمو جارێک بە یەک شێوە وەربگێڕدرێت.</p></section>
<section class="klesson-card"><h2>٢. جێناوی ئاماژەیی یان دیارخەری ئاماژەیی؟</h2><ul><li><strong>بەکارهێنانی سەربەخۆ:</strong> وشەکە بە تەنیا وەک جێناو دێت، بۆ نمونە <em>Ev baş e.</em> — ئەمە باشە.</li><li><strong>لەگەڵ ناو:</strong> وشەی ئاماژەیی لەگەڵ ناو دێت و ناوەکە دیاری دەکات، وەک <em>ev pirtûk</em> — ئەم کتێبە (نمونەی فێرکاری).</li></ul><p>لە ڕێزماندا، بەپێی ئەوەی وشەکە بە تەنیا شوێنی ناو دەگرێتەوە یان ناوێک دیاری دەکات، دەتوانرێت بە جێناوی ئاماژەیی یان دیارخەری ئاماژەیی ناوببرێت.</p></section>
<section class="klesson-card"><h2>٣. نمونە لە ڕستەدا</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th><th>ئەرکی وشەی ئاماژەیی</th></tr></thead><tbody>
<tr><td>Ev baş e.</td><td>ئەمە باشە.</td><td>سەربەخۆ؛ جێناوی ئاماژەیی.</td></tr>
<tr><td>Ew baş e.</td><td>ئەوە باشە / ئەو باشە.</td><td>واتاکە بە کۆنتێکست دیاری دەکرێت.</td></tr>
<tr><td>Ev pirtûk baş e.</td><td>ئەم کتێبە باشە.</td><td>لەگەڵ ناو هاتووە؛ دیارخەر.</td></tr>
<tr><td>Ew mal mezin e.</td><td>ئەو ماڵە گەورەیە.</td><td>لەگەڵ ناو هاتووە؛ دیارخەر.</td></tr>
</tbody></table><p class="klesson-note">ئەم ڕستانە نمونەی فێرکاریین بۆ جیاکردنەوەی ئەرکەکان. شێوەی پەیوەندیی ناو و دیارخەر و ڕێکخستنی ڕستە لە سەرچاوە و شێوەزارەکاندا دەتوانێت جیاوازی هەبێت؛ بۆ بەکارهێنانی زانستی، نمونەکان لە ڕێزمانێکی کورمانجیی دیاریکراودا بپشکنە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>واتای <em>ev</em> و <em>ew</em> بنووسە و بۆ هەر یەک نمونەیەک دروست بکە.</li><li>لە ڕستەی <em>Ev baş e.</em> وشەی ئاماژەیی دیاری بکە و بڵێ بە تەنیا هاتووە یان لەگەڵ ناو.</li><li>جیاوازیی نێوان «ئەمە باشە» و «ئەم کتێبە باشە» بە کورمانجی بنووسە.</li><li>دوو شت لە دەوروبەرت دیاری بکە؛ یەکێکیان نزیک و یەکێکیان دوورە. بە شێوەیەکی سادە بە <em>ev</em> و <em>ew</em> ئاماژەیان پێ بکە.</li><li>لە سەرچاوەیەکی ڕێزمانی، نمونەیەکی تر بدۆزەوە و لەگەڵ ئەم نموونانە بەراوردی بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Thackston, W. M. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>Haig, Geoffrey (2018). “Northern Kurdish (Kurmanjî).” In Geoffrey Haig & Geoffrey Khan (eds.), <em>The Languages and Linguistics of Western Asia: An Areal Perspective</em>, pp. 106–158. Berlin: De Gruyter Mouton. <a href="https://doi.org/10.1515/9783110421682-004" target="_blank" rel="noopener">DOI: 10.1515/9783110421682-004</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — grammar and language resources</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-13.html','kurmanji-course-1','ژمارەکان ١–٢٠','<section class="klesson-card"><h2>١. ژمارەکان لە ١ تا ٢٠</h2><table class="klesson-table"><thead><tr><th>ژمارە</th><th>کورمانجی (لاتینی)</th><th>واتا</th></tr></thead><tbody>
<tr><td>1</td><td>yek</td><td>یەک</td></tr><tr><td>2</td><td>du</td><td>دوو</td></tr><tr><td>3</td><td>sê</td><td>سێ</td></tr><tr><td>4</td><td>çar</td><td>چوار</td></tr><tr><td>5</td><td>pênc</td><td>پێنج</td></tr><tr><td>6</td><td>şeş</td><td>شەش</td></tr><tr><td>7</td><td>heft</td><td>حەوت</td></tr><tr><td>8</td><td>heşt</td><td>هەشت</td></tr><tr><td>9</td><td>neh</td><td>نۆ</td></tr><tr><td>10</td><td>deh</td><td>دە</td></tr><tr><td>11</td><td>yanzdeh</td><td>یازدە</td></tr><tr><td>12</td><td>diwanzdeh</td><td>دوازدە</td></tr><tr><td>13</td><td>sêzdeh</td><td>سێزدە</td></tr><tr><td>14</td><td>çardeh</td><td>چواردە</td></tr><tr><td>15</td><td>panzdeh</td><td>پازدە</td></tr><tr><td>16</td><td>şanzdeh</td><td>شازدە</td></tr><tr><td>17</td><td>hevdeh</td><td>حەڤدە</td></tr><tr><td>18</td><td>hejdeh</td><td>هەژدە</td></tr><tr><td>19</td><td>nozdeh</td><td>نۆزدە</td></tr><tr><td>20</td><td>bîst</td><td>بیست</td></tr>
</tbody></table><p class="klesson-note">لە سەرچاوەکاندا بۆ هەندێک ژمارە چەند شێوەی نوسین هەیە؛ بۆ نمونە ١١، ١٢ و ١٥. لەم وانەیەدا یەک شێوە بۆ فێربون هەڵبژێردراوە، بەڵام لە دەقی ئەکادیمیکدا شێوەی بەکارهاتوو لە سەرچاوەی دیاریکراو پەیویستە بە یەکسانی بپارێزرێت.</p></section>
<section class="klesson-card"><h2>٢. تێبینیی ڕێنووسی</h2><ul><li>پیتە نیشان‌دارەکان وەک <em>ê</em>، <em>ş</em> و <em>ç</em> بە وردی بنووسە؛ پیتەکان بەبێ نیشانە جێگۆڕکێیان پێ مەکە.</li><li>ژمارەی ٣ بە <em>sê</em> نوسراوە، نەک <em>se</em>.</li><li>ژمارەی ٨ بە <em>heşt</em> نوسراوە، و ژمارەی ٢٠ بە <em>bîst</em>.</li><li>هەندێک سەرچاوە لە شێوەی ژمارەکانی ١١–١٦دا جیاوازن؛ هەمان شێوەی سەرچاوەکەت بۆ تەواوی وانە یەکسان بەکاربهێنە.</li></ul></section>
<section class="klesson-card"><h2>٣. ژمارە لە ڕستەدا</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Ez du pirtûkan dixwînim.</td><td>من دوو کتێب دەخوێنمەوە.</td></tr><tr><td>Min sê pênûs hene.</td><td>من سێ پێنووسم هەیە.</td></tr><tr><td>Ew pênc rojan li vir e.</td><td>ئەو بۆ ماوەی پێنج ڕۆژ لێرەیە.</td></tr></tbody></table><p class="klesson-note">ئەم ڕستانە نمونەی فێرکاریین. لە <em>Ez du pirtûkan dixwînim</em>دا، <em>pirtûkan</em> فۆڕمی کۆی ناڕاستەوخۆی <em>pirtûk</em>ە، چونکە بەرکاری کردارێکی ئێستایە؛ هەروەها دەربڕینی ماوەی کات، وەک <em>pênc rojan</em>، لە کورمانجیدا فۆڕمی ناڕاستەوخۆ وەردەگرێت. لە ڕستەکانی دیکەشدا ڕێکخستنی ناو و کردار و شێوەی خاوەنداری بە پێی پێکهاتەی ڕستە دەگۆڕێت. ئەگەر لە سەرچاوەی وانەیەکدا شێوەیەکی تر هەیە، لەو وانەیەدا شێوەی سەرچاوەکە بپارێزە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ژمارەکانی ١ تا ١٠ بە کورمانجی بنووسە.</li><li>واتای <em>yanzdeh</em>، <em>şanzdeh</em> و <em>bîst</em> بنووسە.</li><li>ئەم ژمارانە بە وشە بنووسە: ٤، ٨، ١٢، ١٧، ٢٠.</li><li>سێ شتی ناو ژوورەکەت هەڵبژێرە و ژمارەیان بە کورمانجی بنووسە.</li><li>ژمارەکانی ١١–١٦ لە دوو سەرچاوەدا بەراورد بکە و جیاوازیی نوسینیان تۆمار بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Omniglot. <a href="https://www.omniglot.com/language/numbers/kurdish.htm" target="_blank" rel="noopener">Northern (Kurmanji) Kurdish numbers</a>.</li><li>KurdiPedia, <em>Kurmanji Kurdish, Lesson 2</em> — بەشی Hejmar / Numbers. <a href="https://www.kurdipedia.org/files/books/2023/474430.PDF" target="_blank" rel="noopener">PDF</a>.</li><li>CrowdsourceKurdish. <a href="https://github.com/CrowdsourceKurdish/Kurdish-Numbers-to-Words" target="_blank" rel="noopener">Kurdish (Kurmanji) Numbering Rules</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-14.html','kurmanji-course-1','ڕەنگ و ناوی شتە ڕۆژانەکان','<section class="klesson-card"><h2>١. ناوی ڕەنگەکان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>sor</td><td>سوور</td><td>ڕەنگی سوور.</td></tr>
<tr><td>şîn</td><td>شین</td><td>پیتی ş و î بە وردی بنووسە.</td></tr>
<tr><td>kesk</td><td>سەوز</td><td>لە سەرچاوە و ناوچەکاندا واتای ڕەنگەکە بپشکنە.</td></tr>
<tr><td>zer</td><td>زەرد</td><td>ڕەنگی زەرد.</td></tr>
<tr><td>reş</td><td>ڕەش</td><td>پیتی ş لە کۆتاییدا دەپارێزرێت.</td></tr>
<tr><td>spî</td><td>سپێ</td><td>پیتی î لە کۆتاییدا دەپارێزرێت.</td></tr>
<tr><td>qehweyî</td><td>قاوەیی</td><td>شێوەی وشەکە لە سەرچاوەکاندا دەتوانێت جیاواز بێت.</td></tr>
</tbody></table><p class="klesson-note">لە کورمانجیدا ڕەنگەکان وەک هاوەڵناو بەکاردێن؛ شێوەی ڕستە و ڕێکخستنی وشەکان بە پێی پێکهاتەی ڕێزمانی دەگۆڕێت. لەم وانەیەدا وشەکان بۆ ناسین و ڕاهێنانی سەرەتایی پێشکەش کراون.</p></section>
<section class="klesson-card"><h2>٢. ناوی شتە ڕۆژانەکان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>جۆری شت</th></tr></thead><tbody>
<tr><td>pirtûk</td><td>کتێب</td><td>خوێندن</td></tr>
<tr><td>pênûs</td><td>پێنووس</td><td>نوسین</td></tr>
<tr><td>defter</td><td>دەفتەر</td><td>خوێندن و نوسین</td></tr>
<tr><td>derî</td><td>دەرگا</td><td>ماڵ و بینا</td></tr>
<tr><td>kursî</td><td>کورسی</td><td>کەرەستەی ماڵ</td></tr>
<tr><td>mase</td><td>مێز</td><td>کەرەستەی ماڵ</td></tr>
<tr><td>telefon</td><td>تەلەفۆن</td><td>پەیوەندی</td></tr>
<tr><td>av</td><td>ئاو</td><td>خواردنەوە</td></tr>
<tr><td>nan</td><td>نان</td><td>خواردن</td></tr>
<tr><td>mal</td><td>ماڵ</td><td>شوێن</td></tr>
</tbody></table><p class="klesson-note">وشەی ناوچەیی یان وەرگیراو دەتوانێت لە شێوەزارەکاندا جیاواز بێت. لە نوسینی ئەکادیمیکدا، ئەگەر شێوەیەکی دیاریکراو لە سەرچاوەیەکەوە وەردەگریت، هەمان شێوە بە یەکسانی بەکاربهێنە.</p></section>
<section class="klesson-card"><h2>٣. ڕستەی سادە</h2><table class="klesson-table"><thead><tr><th>ڕستەی کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>Ev pirtûk sor e.</td><td>ئەم کتێبە سوورە.</td></tr>
<tr><td>Ev pênûs reş e.</td><td>ئەم پێنووسە ڕەشە.</td></tr>
<tr><td>Av sar e.</td><td>ئاوەکە ساردە.</td></tr>
<tr><td>Telefon li ser maseyê ye.</td><td>تەلەفۆنەکە لەسەر مێزەکەیە.</td></tr>
<tr><td>Ez pirtûkê dixwînim.</td><td>من کتێبەکە دەخوێنمەوە.</td></tr>
</tbody></table><p class="klesson-note">لە نمونەکاندا وشەی ئاماژەیی و هەندێک پاشگری ڕێزمانی هەن. ئەم ڕستانە بۆ ڕاهێنانی سەرەتایین؛ بۆ بەکارهێنانی فەرمی، شێوەی ڕستە لەگەڵ ڕێزمانی سەرچاوەکەت بپشکنە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ناوی شەش ڕەنگ بە کورمانجی بنووسە و واتاکانیان زیاد بکە.</li><li>ناوی پێنج شتی دەوروبەرت بنووسە؛ هەوڵ بدە شێوەی لاتینی و پیتە تایبەتەکان ڕاست بن.</li><li>بە وشەیەک لە خشتەی ڕەنگەکان ڕستەیەک دروست بکە.</li><li>ڕستەیەک بنووسە کە شتێک و شوێنی ئەو شتە دیاری بکات.</li><li>دوو وشە لە سەرچاوەیەکی دیکەدا بپشکنە و ئەگەر شێوەی جیاوازت بینی، جیاوازییەکە تۆمار بکە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish — language resources</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-15.html','kurmanji-course-1','وشەکانی خێزان','<section class="klesson-card"><h2>١. وشە سەرەتاییەکانی خێزان</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th><th>تێبینی</th></tr></thead><tbody>
<tr><td>malbat</td><td>خێزان</td><td>بۆ کۆی ئەندامانی خێزان بەکاردێت.</td></tr>
<tr><td>dayik</td><td>دایک</td><td>وشەی بنەڕەتی.</td></tr>
<tr><td>bav</td><td>باوک</td><td>وشەی بنەڕەتی.</td></tr>
<tr><td>kur</td><td>کوڕ</td><td>واتا بە پێی ڕستە دەتوانێت بۆ کوڕ/منداڵی نێر بێت.</td></tr>
<tr><td>keç</td><td>کچ</td><td>پیتی ç لە کۆتاییدا دەپارێزرێت.</td></tr>
<tr><td>bira</td><td>برا</td><td>پەیوەندیی برا.</td></tr>
<tr><td>xwişk</td><td>خوشک</td><td>پیتی ş لە نوسینەکەدا گرنگە.</td></tr>
<tr><td>kal</td><td>باپیر</td><td>وشەکە لە هەندێک بەکارهێناندا واتای تەمەن‌دار/پیر هەیە؛ واتای ورد لە سەرچاوە بپشکنە.</td></tr>
<tr><td>pîrik</td><td>داپیر</td><td>بەکارهێنان و شێوەی ناوچەیی دەتوانێت جیاواز بێت.</td></tr>
<tr><td>mêr</td><td>مێرد / پیاو</td><td>واتاکە لە ڕستەدا دیاری دەبێت.</td></tr>
<tr><td>jin</td><td>ژن</td><td>واتاکە بە پێی بەکارهێنان ڕون دەبێتەوە.</td></tr>
<tr><td>zarok</td><td>منداڵ</td><td>وشەی گشتی بۆ منداڵ.</td></tr>
</tbody></table><p class="klesson-note">وشەکانی خێزان لە شێوەزار و سەرچاوە جیاوازەکاندا دەکرێت شێوەی جیاوازیان هەبێت. بۆ ناونانی وردی پەیوەندییەکانی خێزان، واتای وشەکە لە ڕستە و سەرچاوەی دیاریکراودا بپشکنە.</p></section>
<section class="klesson-card"><h2>٢. خاوەنداری و پەیوەندیی خێزانی</h2><p>بۆ باسکردنی ئەندامانی خێزان، لە کورمانجیدا خاوەنداری دەتوانێت بە جێناو و پاشگر یان پێکهاتەی ڕێزمانی دیاریکراو دەرببڕدرێت. لەم ئاستەدا، پێش ئەوەی شێوەیەکی درێژتر فێرببیت، ناوی بنەڕەتیی وشەکان بناسە.</p><table class="klesson-table"><thead><tr><th>دەربڕین</th><th>واتا</th></tr></thead><tbody><tr><td>dayika min</td><td>دایکی من</td></tr><tr><td>bavê min</td><td>باوکی من</td></tr><tr><td>birayê min</td><td>برای من</td></tr><tr><td>xwişka min</td><td>خوشکی من</td></tr></tbody></table><p class="klesson-note">ئەم دەربڕینانە بۆ ناساندنی پێکهاتەی وشەکانن؛ شێوەی پاشگر و ڕێکخستنی ناو دەتوانێت بە پێی حاڵەتی ڕێزمانی و شێوەی ڕستە بگۆڕێت. لە ڕستەی تەواودا بە سەرچاوەی ڕێزمانی پشکنینیان بکە.</p></section>
<section class="klesson-card"><h2>٣. ڕستەی سادە</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody><tr><td>Ev dayika min e.</td><td>ئەمە دایکی منە.</td></tr><tr><td>Navê bavê min Azad e.</td><td>ناوی باوکم ئازادە.</td></tr><tr><td>Ez bi malbata xwe re dijîm.</td><td>من لەگەڵ خێزانەکەم دەژیم.</td></tr></tbody></table><p class="klesson-note">ڕستەکان بۆ ڕاهێنانی سەرەتایین. بۆ فێربونی ڕێزمانی خاوەنداری و حاڵەتەکان، وانەکانی دواتر و سەرچاوەی ڕێزمانی بەکاربهێنە.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>وشەکانی دایک، باوک، برا، خوشک و منداڵ بە کورمانجی بنووسە.</li><li>وشەی <em>malbat</em> لە ڕستەیەکی سادەدا بەکاربهێنە.</li><li>دەربڕینێک بۆ «دایکی من» و «براکەم» بنووسە و لە سەرچاوەیەکی ڕێزمانیدا پشکنینیان بکە.</li><li>بە سێ ڕستە خێزانەکەت بناسێنە؛ ئەگەر ناتەوێت زانیاریی کەسی بەکاربهێنیت، خێزانێکی خەیاڵی هەڵبژێرە.</li><li>جیاوازیی وشەی «کوڕ» و «منداڵ» لە ڕستەی خۆتدا ڕون بکەوە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Yari. <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English dictionary</a>.</li><li>W. M. Thackston. <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings.</em> <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>University of Arizona, Iranian Languages. <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish resources</a>.</li></ol></section>',now()),
  ('kurmanji-course-1-lesson-16.html','kurmanji-course-1','ڕۆژەکانی هەفتە و کات','<section class="klesson-card"><h2>١. ڕۆژەکانی هەفتە</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>duşem</td><td>دووشەممە</td></tr><tr><td>sêşem</td><td>سێشەممە</td></tr><tr><td>çarşem</td><td>چوارشەممە</td></tr><tr><td>pêncşem</td><td>پێنجشەممە</td></tr><tr><td>în</td><td>هەینی</td></tr><tr><td>şemî</td><td>شەممە</td></tr><tr><td>yekşem</td><td>یەکشەممە</td></tr></tbody></table><p class="klesson-note">ناونانی ڕۆژەکان لە سەرچاوە و ناوچە جیاوازەکاندا دەتوانێت شێوەی جیاواز هەبێت. لەم وانەیەدا شێوەیەکی باوی نوسینی کورمانجی بەکار هاتووە؛ بۆ فێربونی ڕێنووسی ناوچەیەکی دیاریکراو، فەرهەنگەکە بە پێی هەمان ناوچە هەڵبژێرە.</p></section>
<section class="klesson-card"><h2>٢. وشەکانی کات</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتا</th></tr></thead><tbody>
<tr><td>roj</td><td>ڕۆژ</td></tr><tr><td>şev</td><td>شەو</td></tr><tr><td>sibê</td><td>سبەی / بەیانیی داهاتوو</td></tr><tr><td>îro</td><td>ئەمڕۆ</td></tr><tr><td>doh</td><td>دوێنێ</td></tr><tr><td>niha</td><td>ئێستا</td></tr><tr><td>paşê</td><td>دواتر</td></tr><tr><td>zû</td><td>زوو</td></tr><tr><td>dereng</td><td>دواکەوتوو / درەنگ</td></tr><tr><td>hefte</td><td>هەفتە</td></tr><tr><td>meh</td><td>مانگ</td></tr><tr><td>sal</td><td>ساڵ</td></tr></tbody></table><p class="klesson-note">بۆ وشەکانی کات، فەرهەنگی کورمانجی بەکاربهێنە و واتای ڕستەیی بپشکنە؛ هەندێک وشە لە ڕستەی جیاوازدا واتای وردی جیاواز دەگرن.</p></section>
<section class="klesson-card"><h2>٣. نمونەی دەربڕین</h2><table class="klesson-table"><thead><tr><th>کورمانجی</th><th>واتای نزیک</th></tr></thead><tbody><tr><td>Îro duşem e.</td><td>ئەمڕۆ دووشەممەیە.</td></tr><tr><td>Ez sibê têm.</td><td>من سبەی دێم.</td></tr><tr><td>Em îro dixwînin.</td><td>ئێمە ئەمڕۆ دەخوێنین.</td></tr><tr><td>Ez niha amade me.</td><td>من ئێستا ئامادەم.</td></tr></tbody></table><p class="klesson-note">ئەم ڕستانە بۆ ڕاهێنانی سەرەتایین و پەیویستە لەگەڵ سەرچاوەی ڕێزمانی و بەکارهێنانی قسەکەرانی کورمانجی پشکنین بکرێن، بە تایبەتی لە نوسینی کاتە داهاتوو و ڕستەی کرداریدا.</p></section>
<section class="klesson-card"><h2>٤. ڕاهێنان</h2><ol><li>ناوی حەوت ڕۆژەکە بە کورمانجی بنووسە و لەبەریان بکە.</li><li>وشەکانی «ئەمڕۆ»، «دوێنێ»، «سبەی» و «ئێستا» بە کورمانجی بنووسە.</li><li>بە یارمەتی فەرهەنگ، ڕستەیەک دروست بکە کە ناوی ڕۆژێک و کاتێک تێدا بێت.</li><li>بەرنامەی خوێندنی خۆت بۆ سێ ڕۆژ بە کورمانجی بنووسە.</li><li>جیاوازیی واتای <em>roj</em> و <em>şev</em> لە نمونەی خۆتدا ڕون بکەوە.</li></ol></section>
<section class="klesson-card"><h2>٥. سەرچاوەکان</h2><ol><li>Yari، <a href="https://yari.krd/dictionary/" target="_blank" rel="noopener">Kurmanji–English word list</a>.</li><li>Yari، <a href="https://yari.krd/learn/" target="_blank" rel="noopener">Learn Kurdish: guides for beginners</a>.</li><li>W. M. Thackston، <em>Kurmanji Kurdish: A Reference Grammar with Selected Readings</em>، <a href="https://sites.fas.harvard.edu/~iranian/Kurmanji/kurmanji_complete.pdf" target="_blank" rel="noopener">PDF</a>.</li><li>University of Arizona، <a href="https://iranian-languages.arizona.edu/node/7" target="_blank" rel="noopener">Kurmanji Kurdish</a>.</li></ol></section>',now())
